import json

def extract_top_level_texts(path):
    data=json.load(open(path))
    out=[]
    for r in data.get('results', []):
        items=r.get('response', {}).get('data', {}).get('items', [])
        for it in items:
            sn=it.get('snippet', {}).get('topLevelComment', {}).get('snippet', {})
            t=sn.get('textOriginal') or sn.get('textDisplay')
            if t: out.append(t)
    return out
